| ============================================================================
|  Metal Slug 1 - asm/mission_streams_0e8524.s
|  ----------------------------------------------------------------------------
|  Wave AAA - LOS STREAMS DE BYTECODE DE LA MISSION VM. Region contigua
|  $0E8524..$0F2FFC, 17 entradas, 43,736 B: TODOS los datos de eventos de
|  mision del juego (que enemigo aparece, donde y cuando, en las 6 misiones).
|
|  Son los 12 destinos de la tabla de punteros MissionStreamPtrs_044266
|  (mission_event_vm_04422a.s) mas el stream de debug $0F260E (override
|  cuando $10FD83 esta armado, ver MissionDriver_Init_0442E6). Cada stream
|  es una secuencia de registros interpretados por MissionDriver_Loop_044368
|  + MissionVM_ExecOp_0443C0; el volcado esta ESTRUCTURADO registro a
|  registro segun los strides exactos de MissionVM_SkipOp_0446B6:
|    op $00 spawn directo, 18 B: +1 flags (b0-1 gate dificultad, b2-3
|           subtipo, b4 no-cuenta, b6/b7 XY absolutos), +2 umbral de
|           scroll ($106F5C), +4 indice de plantilla ($E8000), +6/+8 XY,
|           +A 8 B de parametros copiados a $98(a0) de la tarea.
|    op $01 spawner periodico, 10 B de cabecera (umbral, cadencia, limite
|           de repeticiones, gates) + 1 registro anidado (el spawn).
|    op $02 skip-hasta-$0D, 4 B + registros anidados + marcador $0D (2 B).
|    op $03 select aleatorio, 4 B + N ramas anidadas + marcador $0E (2 B).
|    op $04/$0A/$0B esperas de posicion, 6 B + 2 (o 3) registros anidados.
|    op $05..$09 pausas/reanudaciones, 4 B.
|    op $0C fin de stream (0C 00 FF FF).
|  La sangria de los comentarios refleja el anidamiento real.
|
|  BLOQUES AUX (MissionAux_*): datos auxiliares por mision empaquetados
|  entre el terminador $0C y el siguiente stream; son tablas de words
|  (listas de waypoints/alturas terminadas en $FFFF) referenciadas como
|  inmediatos desde el codigo de los enemigos de esa mision (los origenes
|  exactos van comentados linea a linea).
|
|  Verificacion: el parser recorre los 13 streams completos sin un solo
|  opcode invalido y cada terminador cae exactamente donde empieza el
|  siguiente stream. Todo byte-exacto contra la ROM (match_batch).
| ============================================================================

